package licentivo;
import java.nio.file.*;import java.util.*;
public final class TestVectors{public static void main(String[]args)throws Exception{var fixture=Json.object(Json.parse(Files.readString(Path.of(args.length>0?args[0]:"tests/lease-vectors.json")),131072));Map<String,String>keys=new HashMap<>();Json.object(fixture.get("trusted_keys")).forEach((k,v)->keys.put(k,(String)v));int count=0;for(Object item:(List<?>)fixture.get("vectors")){var v=Json.object(item);boolean ok;try{Client.verify(Json.object(v.get("envelope")),keys,Json.text(v,"product_id"),Json.text(v,"device_id"),Json.number(v,"now"));ok=true;}catch(Exception e){ok=false;}if(ok!=Boolean.TRUE.equals(v.get("valid")))throw new AssertionError(v.get("name"));count++;}System.out.println("Java: "+count+" lease vectors passed");}}
